1:// requirement: REQ-2 — Register; the two teaching scenarios.
2:import { expect, test } from '@playwright/test';
3:import { EXISTING_ACCOUNT, button, entry, expectSignedIn, expectSignedOut,
4:  fillRegistration, newAccount, openRegistration, registerAccount } from './helpers';
5:
6:test('SCN-REQ-2-01: Register with a new username and remain signed in after refresh', async ({ page }) => {
7:  await entry(page);
8:  const account = newAccount();
9:  await registerAccount(page, account);
10:  await page.reload();
11:  await expectSignedIn(page, account);
12:});
13:
14:test('SCN-REQ-2-02: Reject an existing username without creating a session', async ({ page }) => {
15:  const account = { ...newAccount(), username: EXISTING_ACCOUNT.username };
16:  await entry(page);
17:  await openRegistration(page);
18:  await fillRegistration(page, account);
19:  await button(page, 'Next step').click();
20:  await expect(page.getByRole('alert')).toBeVisible();
21:  await page.goto('/');
22:  await page.reload();
23:  await expectSignedOut(page);
24:});
