---input/tests/REQ-4.spec.ts
1:// requirement: REQ-4 — Logout.
2:import { expect, test } from '@playwright/test';
3:import { entry, expectSignedIn, expectSignedOut, newAccount, registerAccount, signIn, signOut } from './helpers';
4:
5:test('SCN-REQ-4-01: Log out and remain signed out after refresh', async ({ page }) => {
6:  const account = newAccount();
7:  await entry(page);
8:  await registerAccount(page, account);
9:  await signOut(page, account);
10:  await page.reload();
11:  await expectSignedOut(page);
12:  await expect(page.getByText(account.username, { exact: true })).toHaveCount(0);
13:});
14:
15:test('SCN-REQ-4-02: Log in again after logout', async ({ page }) => {
16:  const account = newAccount();
17:  await entry(page);
18:  await registerAccount(page, account);
19:  await signOut(page, account);
20:  await signIn(page, account.username, account.password);
21:  await expectSignedIn(page, account);
22:  await page.reload();
23:  await expectSignedIn(page, account);
24:});
---input/tests/helpers.ts
1:import { randomUUID } from 'node:crypto';
2:import { expect, type Locator, type Page } from '@playwright/test';
3:
4:type Surface = Page | Locator;
5:export const AGREEMENT =
6:  'I have read and agree to abide by Terms of Service and Privacy Policy of 12306.cn.';
7:export const link = (surface: Surface, name: string) => surface.getByRole('link', { name, exact: true });
8:export const button = (surface: Surface, name: string) => surface.getByRole('button', { name, exact: true });
9:export const textbox = (surface: Surface, name: string) => surface.getByRole('textbox', { name, exact: true });
10:// Native password inputs have no implicit textbox role; locate them by the required label.
11:export const passwordField = (surface: Surface, name: string) => surface.getByLabel(name, { exact: true });
12:
13:// Seeded by the scenario environment; tests must not use registration to create this Given data.
14:export const EXISTING_ACCOUNT = {
15:  username: 'taken_traveler', email: 'taken.traveler@example.com', password: 'TakenSmoke!2026',
16:};
17:
18:export async function entry(page: Page) { await page.goto('/'); }
19:export async function openRegistration(page: Page) {
20:  await link(page, 'Register').click();
21:  await expect(page).toHaveURL(/\/register\/?$/);
22:  await expect(page.getByRole('combobox', { name: 'Nationality', exact: true })).toBeVisible();
23:}
24:export async function openLogin(page: Page) {
25:  await link(page, 'Login').click();
26:  await expect(page).toHaveURL(/\/login\/?$/);
27:  await expect(textbox(page, 'Email/Username/Mobile number')).toBeVisible();
28:}
29:export function newAccount() {
30:  const identity = randomUUID().replace(/-/g, '').slice(0, 20);
31:  return {
32:    username: `smoke-${identity}`, email: `smoke-${identity}@example.com`,
33:    name: `Traveler ${identity}`, passport: `P${identity}`, password: 'Valid-password-123!',
34:  };
35:}
36:export type Account = ReturnType<typeof newAccount>;
37:export async function expectSignedIn(page: Page, account: { username: string }) {
38:  await expect(page).toHaveURL(/\/$/);
39:  await expect(page.getByText(account.username, { exact: true })).toBeVisible();
40:  await expect(link(page, 'Register')).toHaveCount(0);
41:  await expect(link(page, 'Login')).toHaveCount(0);
42:  await expect(button(page, 'Logout')).toBeVisible();
43:}
44:export async function expectSignedOut(page: Page) {
45:  await expect(link(page, 'Register')).toBeVisible();
46:  await expect(link(page, 'Login')).toBeVisible();
47:  await expect(button(page, 'Logout')).toHaveCount(0);
48:}
49:export async function fillRegistration(page: Page, account: Account) {
50:  const nationality = page.getByRole('combobox', { name: 'Nationality', exact: true });
51:  try {
52:    await nationality.selectOption({ label: 'China' }, { timeout: 1_000 });
53:  } catch {
54:    await nationality.click();
55:    await page.getByRole('option', { name: 'China', exact: true }).click();
56:  }
57:  await textbox(page, 'Name').fill(account.name);
58:  await textbox(page, 'Passport number').fill(account.passport);
59:  await textbox(page, 'Passport expiration date').fill('2099-12-31');
60:  await textbox(page, 'Date of birth').fill('1995-06-15');
61:  await page.getByRole('radiogroup', { name: 'Gender', exact: true })
62:    .getByRole('radio', { name: 'Male', exact: true }).check();
63:  await textbox(page, 'Username').fill(account.username);
64:  await passwordField(page, 'Password').fill(account.password);
65:  await passwordField(page, 'Confirm Password').fill(account.password);
66:  await textbox(page, 'Email address').fill(account.email);
67:  await page.getByRole('checkbox', { name: AGREEMENT, exact: true }).check();
68:}
69:export async function registerAccount(page: Page, account: Account) {
70:  await openRegistration(page);
71:  await fillRegistration(page, account);
72:  await button(page, 'Next step').click();
73:  await expectSignedIn(page, account);
74:}
75:export async function signIn(page: Page, identifier: string, password: string) {
76:  await openLogin(page);
77:  await textbox(page, 'Email/Username/Mobile number').fill(identifier);
78:  await passwordField(page, 'Password').fill(password);
79:  await button(page, 'LOGIN').click();
80:}
